  VALUES 
    (531::BIGINT, 'Es buen profe y si usted va a consulta lo ayuda mucho, pero a la hora de clases, explica muy desordenado, las presentaciones son fotos del libro y no es como ayuden mucho, para eso se lee el libro, pero los quices son fáciles pero los exámenes si califica un toque duro y dura mucho entregando notas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '28bfbccb3edb5e7476bb5e7d18ce4becb625ce3c3ad7648ea35d29e5de77a366'::TEXT, ARRAY[2737]::BIGINT[]),
    (531::BIGINT, 'Allen es buen profe y ayuda bastante, si ud tiene una duda, él siempre va a intentar resolverla. Lo que sí tiene es que es un toque desordenado a la hora de explicar y eso lo puede perder a uno. Dura mucho calificando.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, '24379448f9b124139b60c1f747b750edbcd670333d2cd50756f1505c444b2d92'::TEXT, ARRAY[2737]::BIGINT[]),
    (531::BIGINT, 'No se acopla al cronograma.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'aafbb8e5544a1927c9abef088c8282ea7a57ceb71162ad05a9a13c3011624137'::TEXT, ARRAY[2737]::BIGINT[]),
    (531::BIGINT, 'Un profesor demasiado bueno, si usted no sabe nada, puede preguntar sin problema, muy paciente y explica muy bien. Muy buena persona, si tiene la oportunidad de matricular con el HAGALO no se va a arrepentir. De lo mejor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-01-16T00:00:00+00:00'::TIMESTAMPTZ, '67628bbb79c40f058251d6081296e655fff5a7635aeb29f63d331f4e21755d66'::TEXT, ARRAY[567, 3167, 2813]::BIGINT[]),
    (531::BIGINT, 'increible profe la verdad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-08T00:00:00+00:00'::TIMESTAMPTZ, 'dd4dca5d4c13912f8f2220a933a5d6f9388193e79a8f64ac712fbee0fb704f2a'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Explica bien la materia, las clases son entretenidas, si ud pone atención y hace los ejercicios del folleto pasa bien el curso, super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-04-08T00:00:00+00:00'::TIMESTAMPTZ, '871e3dd23f5d638b03c8df03a0676b43a53b53d772be5827ed18f5bf11afcb18'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Excelente profesor. Tiene un conocimiento muy amplio, y lo usa para sus explicaciones en clase de manera muy clara. Explica cuantas veces sea necesario para que TODOS entiendan. Excelente sacando dudas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '913a68244b08bd957b6d7d496812b727477b0093b0571c2828accab9384c80e5'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Se desvía de los temas por lo que no llega a cosas tan concretas aunque siempre desea explicarse bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '073228a73528c795626a2796043a50ab54da60f3a66fa81275b14424d864ab4b'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-05-13T00:00:00+00:00'::TIMESTAMPTZ, '9dcdfb32c752e5f782336a4e8d12e1331dd2c301679ef29a8c5ea6ba71c65927'::TEXT, ARRAY[3167]::BIGINT[]),
    (531::BIGINT, 'Se le olvidan las cosas, primero te explica algo y luego dice otra cosa, pero demasiado buena gente, ayuda bastante, y sí trata de explicar hasta que a todos les quede claro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'c7af79ffadc3b24139cb50d54cab1e71c4c7d0fffc41e7f8477dfe49fc8a3478'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Allen como persona es muy buena nota, pero como profe, no tanto, el mae puede estar explicando algo y dejarlo botado para hablar de algo que todavía no hay que ver. Es medio enredado, y hace la clase bastante aburrida, se entiende si se le pone atención, lo bueno de Allen es que no califica duro.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '3705affbed1e9e74d714a15ff348d64a01300459aa59ada1c6b8a26ac63a8c18'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'A veces llega un poco tarde y suele hacer la leccion mas larga de lo normal. Cuesta obtener interes en clase porque suelen ser aburridas. Da muchos ejemplos y siempre intenta responder todas las dudas que uno tenga y nunca dude en preguntar, pero es aburrido y desordenado al escribir en la pizarra.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '28d65b08fee774eef2930556624f097b2c0eb5fb9fc11b26261d0fc8d2414af7'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Es muy buen profe pero si quiere que le vaya bien tiene que llevar la materia leída de la casa porque él asume que usted ya estudió, no es como otros profes que le explican la materia en la clase, lo que hace es explicar ejercicios pero si no es de leer antes no le recomiendo que lo lleve con él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '645e55323090344d8cb389d1d38de143b1aa84d3a8b4e9c6f73daf80f1ffd939'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Excelente profe y super buena nota. Le interesa que aprendan sus estudiantes, aclaro las dudas cien veces si es necesario. Hace quices cuando se acerca el examen. No manda tareas. Explica bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a7c471fdd6f8bb352333e2643d12cf39342d4cb2075ebc3a43735bfe6e2a4280'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Muy buena gente, super divertido, cuenta la clase como un cuento, explica muy claro, tiene métodos fáciles para todo, un crack.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '631bd6ebef69786f540fdd83c3aea78aeb68516c477361ab6d0329a270c3376f'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Muy bueno aclarando dudas, explica bastante bien. Pasa una gran parte de las clases aclarando dudas y hace muchos quices.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'eda28f3451375101ee1d6c066b49b2187bbb8ca5cb6d90160a8ce507ba4d25db'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Buen profe, sus clases se vuelven un poco largas y aburridas a veces y se desvia un poco, pero si uno se sienta adelante y le pone ganas el curso se pasa muy facil, hace bastantes quices las semanas antes de examen'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'cf2d16b48d20fb0a729c2fb60067578c4234b5c3fdc42f0f6f393862caedbbb9'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Es buen profesor, y si uno va y pone atención en sus clases mejor! Es bueno hacer practicas de la materia y llevar las dudas, porque a veces se le van detalles. Sin embargo le explica a uno todo lo que uno pregunte de manera muy clara. Solo no matriculen nunca después de almuerzo. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2016-06-09T00:00:00+00:00'::TIMESTAMPTZ, '19e85be47274d6e3cb638483d7e56559f9ca3806eb1e2c4da8550f4b2adad869'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'c0c1b7a7da74e43a6dfff2cfdf0a4db722cbc363d5ca1efc4d833771d8d0931f'::TEXT, ARRAY[567, 3167, 2813]::BIGINT[]),
    (531::BIGINT, 'Excelente profesor! En veces se le olvidan detalles importantes para el examen pero es un profesor muy accesible para preguntarle alguna duda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '98de72f41bb20d02862a93766ce15a6018bedd87bd6496030767c5e42cad9f8e'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Te ayuda en lo que puede, aveces no es 100% claro, pero se le entiende si usted asiste a todas sus clases. Una gran persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ff74ac1cc4dd40c9cc46463ad1ebdab187dda8cca01455e102e6359f8fcb488f'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Cuesta entenderle, a menos de que lleve el hilo de todas las clases al 100%, es fácil, pero se le van algunos detalles de la materia'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-31T00:00:00+00:00'::TIMESTAMPTZ, '3a5bf044fd510d390af208ed5745d3c51949d8c546bf3494a0f31469cb0b86f1'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Allen está dispuesto a ayudar a sus estudiantes lo mejor que pueda, pero sus clases suelen ser muy confusas y definitivamente le falta pedagogía. Los quices los hace con la dificultad del examen, por lo que si no lleva la materia al día espere que le vaya bastante mal en ellos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2016-05-25T00:00:00+00:00'::TIMESTAMPTZ, '2ff158d76f9b209397a646870b425ae8d3507ecbcf672276f5d311d459009c64'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2016-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'd2e0ca8e6a96dfc2aa72507ddf4e00ffb16114fb5dc91d9bb3481cc50f519f79'::TEXT, ARRAY[567]::BIGINT[]),
    (531::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-04-27T00:00:00+00:00'::TIMESTAMPTZ, '89fbdd3b1a341fc6c68dff5884327d5710d479f8ec8155d77d941ceaffd8f94f'::TEXT, ARRAY[567]::BIGINT[]),
